shapes:
@prefix sh:   <http://www.w3.org/ns/shacl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix amlo: <https://example.org/amlo#> .
@prefix amx:  <https://example.org/amltrix/> .
@prefix ex:   <https://example.org/rules#> .

# DRAFT example, written for this demo. AML typology (AMLTRIX) itself contains no rules like these.
# It describes technique T0039 "Circular Transactions" (tactic ML.TA0007 Layering) and indicator IND02191 in words:
#   "Cyclical patterns in funds or asset transfers that ultimately revert to the same origin across multiple accounts
#    or entities, lacking a legitimate business rationale."
# The shapes below turn the checkable parts of that sentence into rules on a candidate record (a chain of transfer legs).

ex:rules owl:imports amx: ;
    rdfs:comment "Rules that a candidate record must satisfy before it can be called an instance of T0039 / IND02191." .

ex: sh:declare [ sh:prefix "ex" ; sh:namespace "https://example.org/rules#"^^xsd:anyURI ] ,
               [ sh:prefix "amlo" ; sh:namespace "https://example.org/amlo#"^^xsd:anyURI ] ,
               [ sh:prefix "xsd" ; sh:namespace "http://www.w3.org/2001/XMLSchema#"^^xsd:anyURI ] .

# ---------------------------------------------------------------- one leg of the chain
ex:LegShape a sh:NodeShape ;
    sh:targetClass ex:Leg ;
    sh:property [ sh:path ex:seq    ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A leg needs its position in the chain (ex:seq, an integer from 1)." ] ;
    sh:property [ sh:path ex:from   ; sh:nodeKind sh:IRI ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A leg needs exactly one paying account." ] ;
    sh:property [ sh:path ex:to     ; sh:nodeKind sh:IRI ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A leg needs exactly one receiving account." ] ;
    sh:property [ sh:path ex:amount ; sh:datatype xsd:decimal ; sh:minExclusive 0 ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A leg needs a positive amount." ] ;
    sh:property [ sh:path ex:at     ; sh:datatype xsd:dateTime ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A leg needs one timestamp." ] ;
    # a transfer from an account to itself is not a step in a cycle
    sh:property [ sh:path ex:from ; sh:disjoint ex:to ;
                  sh:message "A leg must go between two different accounts." ] .

# ---------------------------------------------------------------- the loop as a whole
ex:CircularTransactionShape a sh:NodeShape ;
    sh:targetClass ex:LoopCandidate ;
    ex:implementsTechnique amx:T0039 ;     # Circular Transactions
    ex:implementsIndicator amx:IND02191 ;  # "...revert to the same origin across multiple accounts..."
    ex:underTactic         amx:ML.TA0007 ; # Layering
    rdfs:comment "Structural reading of IND02191. It cannot judge intent: whether the cycle lacks a business rationale is for the investigator." ;

    sh:property [ sh:path ex:origin ; sh:nodeKind sh:IRI ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A loop candidate names the account where the funds start (ex:origin)." ] ;

    # "across multiple accounts": at least three transfers
    sh:property [ sh:path ex:leg ; sh:class ex:Leg ; sh:minCount 3 ;
                  sh:message "A loop needs at least 3 legs (two legs is a round trip, not a chain across multiple accounts)." ] ;

    # "revert to the same origin": the first leg starts at the origin, the last leg ends there
    sh:sparql [
        a sh:SPARQLConstraint ; sh:prefixes ex: ;
        sh:message "The first leg must start at the origin account." ;
        sh:select """
            SELECT $this ?value WHERE {
                $this ex:origin ?o ; ex:leg ?l .
                ?l ex:seq 1 ; ex:from ?value .
                FILTER (?value != ?o)
            }""" ] ;
    sh:sparql [
        a sh:SPARQLConstraint ; sh:prefixes ex: ;
        sh:message "The last leg must end at the origin account: the funds must return to where they started." ;
        sh:select """
            SELECT $this ?value WHERE {
                $this ex:origin ?o ; ex:leg ?last .
                ?last ex:seq ?s ; ex:to ?value .
                FILTER NOT EXISTS { $this ex:leg ?later . ?later ex:seq ?s2 . FILTER (?s2 > ?s) }
                FILTER (?value != ?o)
            }""" ] ;

    # a chain: each leg pays from the account the previous leg paid to
    sh:sparql [
        a sh:SPARQLConstraint ; sh:prefixes ex: ;
        sh:message "Consecutive legs must connect: a leg starts at the account the previous leg paid to." ;
        sh:select """
            SELECT $this ?value WHERE {
                $this ex:leg ?a , ?b .
                ?a ex:seq ?s1 ; ex:to ?value .
                ?b ex:seq ?s2 ; ex:from ?f .
                FILTER (?s2 = ?s1 + 1 && ?value != ?f)
            }""" ] ;

    # the funds move forward in time
    sh:sparql [
        a sh:SPARQLConstraint ; sh:prefixes ex: ;
        sh:message "Legs must be in time order: a leg cannot happen before the one it follows." ;
        sh:select """
            SELECT $this ?value WHERE {
                $this ex:leg ?a , ?b .
                ?a ex:seq ?s1 ; ex:at ?t1 .
                ?b ex:seq ?s2 ; ex:at ?value .
                FILTER (?s2 = ?s1 + 1 && ?value < ?t1)
            }""" ] ;

    # "multiple accounts": a cycle that passes through the same account twice is two smaller cycles
    sh:sparql [
        a sh:SPARQLConstraint ; sh:prefixes ex: ;
        sh:message "A loop must pass through at least 3 different accounts, each paying once." ;
        sh:select """
            SELECT $this WHERE {
                $this ex:leg ?l . ?l ex:from ?f .
            } GROUP BY $this HAVING (COUNT(DISTINCT ?f) < 3)""" ] ;

    # "lacking a legitimate business rationale": the shape cannot decide this, it can only point at a record that claims one
    sh:property [ sh:path ex:documentedRationale ; sh:maxCount 0 ; sh:severity sh:Warning ;
                  sh:message "A business rationale is recorded for this cycle. IND02191 describes cycles that lack one: review before treating it as a match." ] .

# ---------------------------------------------------------------- a finding that cites the typology: technique and tactic must agree
# This one reads the typology itself (amltrix.ttl must be in the same graph).
ex:FindingShape a sh:NodeShape ;
    sh:targetClass ex:Finding ;
    sh:property [ sh:path ex:technique ; sh:class amlo:Technique ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A finding cites exactly one technique from the typology." ] ;
    sh:property [ sh:path ex:tactic ; sh:minCount 1 ; sh:maxCount 1 ;
                  sh:message "A finding names exactly one tactic." ] ;
    sh:sparql [
        a sh:SPARQLConstraint ; sh:prefixes ex: ;
        sh:message "The typology does not list this technique under the tactic the finding names." ;
        sh:select """
            SELECT $this ?value WHERE {
                $this ex:technique ?t ; ex:tactic ?value .
                FILTER NOT EXISTS { ?link a amlo:TacticLink ; amlo:technique ?t ; amlo:tactic ?value }  # the typology links them through a TacticLink node
            }""" ] .
